import { randint } from "tstl";
import typia, { tags } from "typia";

import { authorize_super_admin_join } from "../../../authorize/authorize_super_admin_join";
import { authorize_super_admin_login } from "../../../authorize/authorize_super_admin_login";
import { authorize_super_admin_refresh } from "../../../authorize/authorize_super_admin_refresh";

/**
 * Test super administrator retrieval of paginated administrator list.
 *
 * Validates that a super administrator can successfully retrieve a paginated list of all administrators on the platform. This test verifies the complete pagination workflow including authentication, list retrieval, and response structure validation.
 *
 * The test ensures that the pagination metadata is accurate, administrator summaries contain all required fields, and the status field is correctly computed based on banned_at and deleted_at timestamps.
 *
 * 1. Super administrator registers and authenticates via authorize_super_admin_join.
 * 2. Calls PATCH /shoppingMall/superAdmin/admins with default pagination parameters.
 * 3. Validates pagination metadata structure and values.
 * 4. Validates each administrator summary contains required fields.
 * 5. Validates status computation logic (active/banned/deleted).
 * 6. Validates results are sorted by created_at descending.
 * 7. Validates password_hash is excluded from response.
 */
export async function test_api_administrator_list_pagination(
  connection: api.IConnection,
): Promise<void> {
  // 1. Register and authenticate as super administrator
  const superAdminConnection: api.IConnection = { host: connection.host };
  const authResult = await authorize_super_admin_join(superAdminConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: typia.random<string & tags.Format<"ipv4">>(),
    } satisfies IShoppingMallSuperAdmin.IJoin,
  });
  typia.assert(authResult);
  // 2. Retrieve paginated administrator list with default parameters
  const response = await api.functional.shoppingMall.superAdmin.admins.index(
    superAdminConnection,
    {
      body: {
        page: 1,
        limit: 20,
      } satisfies IShoppingMallAdmin.IRequest,
    },
  );
  typia.assert(response);
  // 3. Validate pagination metadata values
  TestValidator.equals("current page", response.pagination.current, 1);
  TestValidator.equals("limit", response.pagination.limit, 20);
  TestValidator.predicate(
    "records count non-negative",
    response.pagination.records >= 0,
  );
  TestValidator.predicate(
    "pages count non-negative",
    response.pagination.pages >= 0,
  );
  // 4. Validate each administrator summary business logic
  for (const admin of response.data) {
    // Validate grade is either 'regular' or 'super'
    TestValidator.predicate(
      "grade is valid",
      admin.grade === "regular" || admin.grade === "super",
    );
    // Validate status is one of expected values
    TestValidator.predicate(
      "status is valid",
      admin.status === "active" ||
        admin.status === "banned" ||
        admin.status === "deleted",
    );
    // Validate status computation logic based on banned_at
    if (admin.banned_at !== null) {
      TestValidator.equals(
        "banned status when banned_at is set",
        admin.status,
        "banned",
      );
    }
    // Validate member profile has required fields (typia.assert already validated structure)
    TestValidator.predicate("member has id", admin.member.id !== undefined);
    TestValidator.predicate(
      "member has email",
      admin.member.email !== undefined,
    );
    // Validate password_hash is NOT included (security check)
    TestValidator.predicate(
      "password_hash not in response",
      !("password_hash" in admin),
    );
  }
  // 5. Validate sorting by created_at descending (newest first)
  if (response.data.length > 1) {
    for (let i = 0; i < response.data.length - 1; i++) {
      const current = new Date(response.data[i].created_at).getTime();
      const next = new Date(response.data[i + 1].created_at).getTime();
      TestValidator.predicate(
        `sorted descending at index ${i}`,
        current >= next,
      );
    }
  }
  // 6. Validate pagination metadata consistency
  if (response.pagination.records === 0) {
    TestValidator.equals(
      "pages is 0 when no records",
      response.pagination.pages,
      0,
    );
    TestValidator.equals(
      "data is empty when no records",
      response.data.length,
      0,
    );
  } else {
    const expectedPages = Math.ceil(
      response.pagination.records / response.pagination.limit,
    );
    TestValidator.equals(
      "pages calculation correct",
      response.pagination.pages,
      expectedPages,
    );
  }
}

