  typia.assert(auth3);
  // Create fourth super admin with different pattern (should not match)
  const superAdmin4Connection: api.IConnection = { host: connection.host };
  const auth4 = await authorize_super_admin_join(superAdmin4Connection, {
    body: {
      email: email4,
