/**
 * Test successful retrieval of a customer's own shipping address.
 *
 * Validates the complete address retrieval flow including member authentication, address creation, and single address retrieval by ID. Ensures that customers can only access their own addresses and that all address fields are correctly returned.
 *
 * Special attention is given to verifying that the address belongs to the authenticated customer, all required fields match the creation input, and the nested customerProfile object contains correct ownership information.
 *
 * 1. Member registers with email and password credentials via authorize_member_join.
 * 2. Member creates a shipping address with complete information using generate_random_shopping_mall_member_addresses_create.
 * 3. Member retrieves the address by ID via GET /shoppingMall/member/addresses/{addressId}.
 * 4. Validates address fields match creation including recipient name, phone, street address, city, state, postal code, country, and is_default flag.
 * 5. Verifies customerProfile object is present with correct display_name and phone_number.
 * 6. Confirms created_at and updated_at timestamps are valid ISO 8601 format and deleted_at is null.
 */
export async function test_api_customer_address_retrieval_success(
  connection: api.IConnection,
): Promise<void> {
  // 1. Member registration
  const memberConnection: api.IConnection = { host: connection.host };
  const member = await authorize_member_join(memberConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IShoppingMallMember.IJoin,
  });
  typia.assert(member);
  // 2. Create shipping address
  const address = await generate_random_shopping_mall_member_addresses_create(
    memberConnection,
    {},
  );
  typia.assert(address);
  // 3. Retrieve address by ID
  const retrieved = await api.functional.shoppingMall.member.addresses.at(
    memberConnection,
    {
      addressId: address.id,
    },
  );
  typia.assert(retrieved);
  // 4. Validate address ID matches
  TestValidator.equals("address ID", retrieved.id, address.id);
  // 5. Validate address fields match creation
  TestValidator.equals(
    "recipient name",
    retrieved.recipient_name,
    address.recipient_name,
  );
  TestValidator.equals(
    "recipient phone",
    retrieved.recipient_phone,
    address.recipient_phone,
  );
  TestValidator.equals(
    "street address",
    retrieved.street_address,
    address.street_address,
  );
  TestValidator.equals("city", retrieved.city, address.city);
  TestValidator.equals(
