import { authorize_admin_refresh } from "../../../authorize/authorize_admin_refresh";

/**
 * Test administrator list pagination functionality with authenticated access.
 *
 * Validates the complete administrator listing flow including administrator authentication, paginated list retrieval, and response structure validation. Ensures that the pagination metadata is correctly returned and that administrator summaries contain all required fields including nested member information.
 *
 * The test verifies that administrators can be listed with proper pagination controls, that the response includes accurate pagination metadata (current page, limit, total records, total pages), and that each administrator summary contains the expected fields including grade level and member profile information.
 *
 * 1. Administrator account is created and authenticated using authorize_admin_join.
 * 2. Paginated list of administrators is retrieved with default parameters.
 * 3. Response structure is validated against IPageIShoppingMallAdministrator.ISummary schema.
 * 4. Pagination metadata is verified to contain all required fields with correct types.
 * 5. Administrator summaries are validated to include id, grade, created_at, and member data.
 * 6. Member information is validated to include id, email, status, created_at, and customerProfile.
 * 7. Test is repeated with explicit pagination parameters to verify pagination controls work.
 * 8. Sorting by created_at descending is validated when multiple administrators exist.
 */
export async function test_api_administrator_list_pagination(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create and authenticate administrator account
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      grade: "regular",
    } satisfies IShoppingMallAdmin.IJoin,
  });
  // 2. Retrieve administrators list with default pagination
  const defaultResult =
    await api.functional.shoppingMall.admin.administrators.index(
      adminConnection,
      {
        body: {} satisfies IShoppingMallAdministrator.IRequest,
      },
    );
  typia.assert(defaultResult);
  // 3. Validate pagination metadata exists and has correct structure
  TestValidator.predicate(
    "pagination exists",
    defaultResult.pagination !== undefined,
  );
  TestValidator.predicate(
    "data array exists",
    Array.isArray(defaultResult.data),
  );
  // 4. Validate administrator summaries structure (if any exist)
  if (defaultResult.data.length > 0) {
    const admin = defaultResult.data[0];
    // Validate member information exists
    TestValidator.predicate("member exists", admin.member !== undefined);
    // Validate customer profile structure (can be null)
    if (admin.member.customerProfile !== null) {
      typia.assertGuard(admin.member.customerProfile!);
      TestValidator.predicate(
        "customer profile has display name",
        admin.member.customerProfile.display_name.length > 0,
      );
    }
  }
  // 5. Test with explicit pagination parameters
  const explicitResult =
    await api.functional.shoppingMall.admin.administrators.index(
      adminConnection,
      {
        body: {
          page: 1,
          limit: 20,
        } satisfies IShoppingMallAdministrator.IRequest,
      },
    );
  typia.assert(explicitResult);
  // 6. Validate explicit pagination parameters are respected
  TestValidator.equals(
    "current page matches",
    explicitResult.pagination.current,
    1,
  );
  TestValidator.predicate(
    "limit is 20 or less",
    explicitResult.pagination.limit <= 20,
  );
  // 7. Validate sorting by created_at descending (if multiple admins exist)
  if (explicitResult.data.length > 1) {
    for (let i = 1; i < explicitResult.data.length; i++) {
      const prev = explicitResult.data[i - 1];
      const curr = explicitResult.data[i];
      TestValidator.predicate(
        "sorted by created_at descending",
        new Date(prev.created_at).getTime() >=
          new Date(curr.created_at).getTime(),
      );
    }
  }
}

