 * Validates the complete rejection workflow including member account creation, promotion request submission, super administrator rejection with note, and retrieval of the rejected request. Ensures that rejected requests properly preserve all rejection metadata for applicant visibility and audit trail purposes.
 *
 * Special attention is given to verifying that the rejection_note field contains the explanation provided during rejection, the reviewer object is populated with super administrator details, and the status correctly reflects the rejected state.
 *
 * 1. Super administrator account created via join endpoint.
 * 2. Member account created via join and promotion request submitted with reason.
 * 3. Super administrator rejects the request with rejection note.
 * 4. Retrieve the rejected promotion request by ID.
 * 5. Verify status is 'rejected', reviewer is populated, rejection_note matches input, and actor_type is 'member'.
 */
export async function test_api_admin_promotion_request_view_rejected(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create super administrator account
  const superAdminConnection: api.IConnection = { host: connection.host };
