/**
 * Test product variant listing returns empty page when product has no variants.
 *
 * Validates the edge case where a product exists but has no variants. A seller creates a product without adding any variants, then attempts to list variants for that product. The system should return an empty page with correct pagination metadata rather than an error response.
 *
 * This scenario validates the business rule that products can exist without variants but are shown as unavailable to customers until at least one variant is added. The empty result should still include the pagination structure with zero records, allowing the frontend to handle the no-variants state gracefully.
 *
 * 1. Administrator creates an account and logs in.
 * 2. Administrator creates a category for the product.
 * 3. Seller creates an account and logs in.
 * 4. Seller creates a product without any variants.
 * 5. Seller lists variants for the product.
 * 6. Validates empty page response with correct pagination metadata (records: 0, pages: 0, current: 1, data: []).
 */
export async function test_api_product_variant_listing_empty_result(
  connection: api.IConnection,
): Promise<void> {
  // 1. Admin setup - create and login
  const adminConnection: api.IConnection = { host: connection.host };
  const adminAuth = await authorize_admin_join(adminConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      grade: "regular" as const,
    },
  });
  typia.assert(adminAuth);
  // 2. Create category for product
  const category =
    await generate_random_shopping_mall_admin_categories_create(
      adminConnection,
      {},
    );
  typia.assert(category);
  // 3. Seller setup - create and login
  const sellerConnection: api.IConnection = { host: connection.host };
  const sellerAuth = await authorize_seller_join(sellerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  typia.assert(sellerAuth);
  // 4. Create product without variants
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        shopping_mall_category_id: category.id,
      },
    },
  );
  typia.assert(product);
  // 5. List variants for the product (should be empty)
  const variantList =
    await api.functional.shoppingMall.seller.products.variants.index(
      sellerConnection,
      {
        productId: product.id,
        body: {
          page: 1,
          limit: 20,
        } satisfies IShoppingMallProductVariant.IRequest,
      },
    );
  typia.assert(variantList);
  // 6. Validate empty page with correct pagination
  TestValidator.equals("records count", variantList.pagination.records, 0);
  TestValidator.equals("pages count", variantList.pagination.pages, 0);
  TestValidator.equals("current page", variantList.pagination.current, 1);
  TestValidator.equals("limit", variantList.pagination.limit, 20);
  TestValidator.equals("data array length", variantList.data.length, 0);
}

