 *
 * Validates the complete product variant creation workflow including seller authentication, product setup, and variant creation. Ensures that the variant is correctly associated with the parent product and that all required fields are properly populated.
 *
 * Special attention is given to verifying that the SKU code is unique within the product context, the option values provide human-readable descriptions, and the price field correctly handles null values to inherit the product's base price.
 *
 * 1. Seller registers and authenticates with valid credentials.
 * 2. Administrator creates a category for product organization.
 * 3. Seller creates a product with name, description, category, and base price.
 * 4. Seller creates a variant for the product with SKU code, option values, and null price.
 * 5. Validates variant details match input and product relation, timestamps are set, and variant is active.
 */
export async function test_api_product_variant_creation_success(
  connection: api.IConnection,
): Promise<void> {
  // 1. Seller setup - register and authenticate
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "TestPassword123!",
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IShoppingMallSeller.IJoin,
  });
  // 2. Admin setup - register and authenticate to create category
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "AdminPassword123!",
      grade: "regular" as const,
