  // 4. Seller creates product
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        name: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.content({ paragraphs: 2 }),
        shopping_mall_category_id: category.id,
        base_price: typia.random<
          number & tags.Type<"uint32"> & tags.Minimum<1000>
        >(),
      },
    },
  );
  typia.assert(product);
  // 5. Seller creates variant for product
  const variant =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
        body: {
          sku_code: "RED-LARGE",
          option_values: "Color: Red, Size: Large",
          price: null,
        },
      },
    );
  typia.assert(variant);
  // 6. Validate variant creation
  TestValidator.equals("sku_code matches", variant.sku_code, "RED-LARGE");
  TestValidator.equals(
    "option_values matches",
    variant.option_values,
    "Color: Red, Size: Large",
  );
  TestValidator.equals("price is null", variant.price, null);
  TestValidator.equals("product id matches", variant.product.id, product.id);
  TestValidator.equals(
    "product name matches",
    variant.product.name,
    product.name,
  );
  TestValidator.equals(
    "product base_price matches",
    variant.product.base_price,
    product.base_price,
  );
  TestValidator.predicate("created_at is set", variant.created_at !== null);
  TestValidator.predicate("updated_at is set", variant.updated_at !== null);
  TestValidator.equals("deleted_at is null", variant.deleted_at, null);
}

