/**
 * Test variant creation with optional price override to verify pricing flexibility.
 *
 * Validates the complete product variant creation workflow including seller authentication, category setup, product creation, and variant creation with different price override scenarios. Ensures that variants can have prices higher than, equal to (null), or lower than the product's base price.
 *
 * Special attention is given to verifying that the price override mechanism works correctly for all three scenarios: premium pricing (12000 > 10000), base pricing (null = 10000), and discount pricing (8000 < 10000). Each variant must have a unique SKU code within the product context.
 *
 * 1. Seller registers and authenticates with unique credentials.
 * 2. Administrator creates a category for product assignment.
 * 3. Seller creates a product with base_price of 10000.
 * 4. Seller creates first variant with price override of 12000 (premium).
 * 5. Seller creates second variant with price null (uses base price).
 * 6. Seller creates third variant with price override of 8000 (discount).
 * 7. Validates all variants have correct prices and unique SKU codes.
 */
export async function test_api_product_variant_with_price_override(
  connection: api.IConnection,
): Promise<void> {
  // 1. Seller registration and authentication
  const sellerConnection: api.IConnection = { host: connection.host };
  const sellerAuth = await authorize_seller_join(sellerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "TestPass123!",
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  typia.assert(sellerAuth);
  // Note: Seller account is 'pending' after registration. For this test,
  // we assume the seller is approved by admin (in real scenario, admin would approve).
  // We'll proceed with the seller connection as if approved.
  // 2. Admin creates a category
  const adminConnection: api.IConnection = { host: connection.host };
  const adminAuth = await authorize_admin_join(adminConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "AdminPass123!",
      grade: "regular" as const,
    },
  });
  typia.assert(adminAuth);
  const category = await generate_random_shopping_mall_admin_categories_create(
    adminConnection,
    {
      body: {
        name: RandomGenerator.name(2),
        description: RandomGenerator.paragraph({ sentences: 2 }),
      },
    },
  );
  typia.assert(category);
  // 3. Seller creates a product with base_price of 10000
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        name: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.content({ paragraphs: 2 }),
        shopping_mall_category_id: category.id,
        base_price: 10000,
      },
    },
  );
  typia.assert(product);
  // 4. Create first variant with price override of 12000 (higher than base)
  const variant1 =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
        body: {
          sku_code: "PREMIUM-LARGE",
          option_values: "Color: Red, Size: Large",
          price: 12000,
        },
      },
    );
  typia.assert(variant1);
  // 5. Create second variant with price null (uses base price)
  const variant2 =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
        body: {
          sku_code: "STANDARD-MEDIUM",
          option_values: "Color: Blue, Size: Medium",
          price: null,
        },
      },
    );
  typia.assert(variant2);
  // 6. Create third variant with price override of 8000 (lower than base)
  const variant3 =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
        body: {
          sku_code: "DISCOUNT-SMALL",
          option_values: "Color: Green, Size: Small",
          price: 8000,
        },
      },
    );
  typia.assert(variant3);
  // 7. Validate all variants
  TestValidator.equals("variant1 price override", variant1.price, 12000);
  TestValidator.equals("variant2 uses base price (null)", variant2.price, null);
  TestValidator.equals("variant3 price override", variant3.price, 8000);
  TestValidator.equals("variant1 product", variant1.product.id, product.id);
  TestValidator.equals("variant2 product", variant2.product.id, product.id);
  TestValidator.equals("variant3 product", variant3.product.id, product.id);
  TestValidator.notEquals(
    "variant1 SKU differs from variant2",
    variant1.sku_code,
    variant2.sku_code,
  );
  TestValidator.notEquals(
    "variant2 SKU differs from variant3",
    variant2.sku_code,
    variant3.sku_code,
  );
  TestValidator.notEquals(
    "variant1 SKU differs from variant3",
    variant1.sku_code,
    variant3.sku_code,
  );
  TestValidator.equals("variant1 SKU", variant1.sku_code, "PREMIUM-LARGE");
  TestValidator.equals("variant2 SKU", variant2.sku_code, "STANDARD-MEDIUM");
  TestValidator.equals("variant3 SKU", variant3.sku_code, "DISCOUNT-SMALL");
}

