/**
 * Test that a seller cannot view snapshots of products owned by other sellers (access control enforcement).
 *
 * Validates the access control mechanism that prevents sellers from accessing product snapshots belonging to other sellers. This test ensures that the authorization system properly verifies product ownership before granting access to snapshot data.
 *
 * The test creates two seller accounts (Seller A and Seller B) with distinct identities. Seller B creates a product under an administrator-created category. Seller A then attempts to access the snapshots of Seller B's product, which should be rejected with an authorization error.
 *
 * 1. Administrator creates account, authenticates, and creates a product category.
 * 2. Seller A registers account and authenticates (will attempt unauthorized access).
 * 3. Seller B registers account and authenticates (will create the product).
 * 4. Seller B creates a product under the administrator-created category.
 * 5. Seller A attempts to call PATCH /shoppingMall/seller/products/{productId}/snapshots with Seller B's product ID.
 * 6. Validates that the request fails with HTTP 403 Forbidden indicating insufficient permissions.
 * 7. Confirms that access control properly enforces ownership boundary between sellers.
 */
export async function test_api_product_snapshot_seller_unauthorized_access(
  connection: api.IConnection,
): Promise<void> {
  // 1. Administrator setup - create category
  const adminConnection: api.IConnection = { host: connection.host };
  const adminAuth = await authorize_admin_join(adminConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      grade: "regular" as const,
    },
  });
  typia.assert(adminAuth);
  adminConnection.headers = {
    Authorization: `Bearer ${adminAuth.token.access}`,
  };
  const category = await generate_random_shopping_mall_admin_categories_create(
    adminConnection,
    {},
  );
  typia.assert(category);
  // 2. Seller A setup - will attempt unauthorized access
  const sellerAConnection: api.IConnection = { host: connection.host };
  const sellerAAuth = await authorize_seller_join(sellerAConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  typia.assert(sellerAAuth);
  sellerAConnection.headers = {
    Authorization: `Bearer ${sellerAAuth.token.access}`,
  };
  // 3. Seller B setup - will create the product
  const sellerBConnection: api.IConnection = { host: connection.host };
  const sellerBAuth = await authorize_seller_join(sellerBConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  typia.assert(sellerBAuth);
  sellerBConnection.headers = {
    Authorization: `Bearer ${sellerBAuth.token.access}`,
  };
  // 4. Seller B creates a product
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerBConnection,
    {
      body: {
        shopping_mall_category_id: category.id,
      },
    },
  );
  typia.assert(product);
  // 5. Seller A attempts to access Seller B's product snapshots (should fail)
  await TestValidator.error(
    "seller A cannot access seller B's product snapshots",
    async () => {
      await api.functional.shoppingMall.seller.products.snapshots.index(
        sellerAConnection,
        {
          productId: product.id,
          body: {
            page: 1,
            limit: 10,
          } satisfies IShoppingMallProductSnapshot.IRequest,
        },
      );
    },
  );
}

