/**
 * Test cancellation request snapshot status filtering for seller audit trail.
 *
 * Validates the complete snapshot history querying capabilities for cancellation requests. Tests that sellers can filter snapshots by status (pending, approved, rejected), use pagination parameters, and apply time-range filters using reviewedAtFrom and reviewedAtTo. This ensures proper audit trail functionality for dispute resolution.
 *
 * The test establishes a complete order flow: admin creates category, seller creates product with variant, customer places order, and creates cancellation request. Then validates snapshot filtering at each workflow state.
 *
 * 1. Administrator creates a product category for organization.
 * 2. Seller creates a product and variant for customer purchase.
 * 3. Customer creates shipping address for order delivery.
 * 4. Customer adds variant to cart and places order.
 * 5. Customer creates cancellation request for the order item.
 * 6. Seller queries snapshots with status='pending' filter - verifies initial snapshot exists.
 * 7. Seller queries snapshots with status='approved' filter - verifies response snapshot exists.
 * 8. Seller queries snapshots without filter - verifies all snapshots in chronological order.
 * 9. Seller queries with pagination parameters - verifies page and limit work correctly.
 * 10. Seller queries with reviewedAtFrom/reviewedAtTo - verifies time-range filtering.
 */
export async function test_api_cancellation_request_snapshot_status_filtering(
  connection: api.IConnection,
): Promise<void> {
  // 1. Admin setup - create category
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {});
  const category = await generate_random_shopping_mall_admin_categories_create(
    adminConnection,
    {},
  );
  typia.assert(category);
  // 2. Seller setup - create product and variant
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {});
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        shopping_mall_category_id: category.id,
      },
    },
  );
  typia.assert(product);
  const variant = await generate_random_shopping_mall_seller_variants_create(
    sellerConnection,
    {
      body: {
        shopping_mall_product_id: product.id,
      },
    },
  );
  typia.assert(variant);
  // 3. Customer setup - create address and place order
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_member_join(customerConnection, {});
  const address = await generate_random_shopping_mall_member_addresses_create(
    customerConnection,
    {},
  );
  typia.assert(address);
  const cartItem = await generate_random_shopping_mall_member_cart_items_create(
    customerConnection,
    {
      body: {
        product_variant_id: variant.id,
      },
    },
  );
  typia.assert(cartItem);
  const order = await generate_random_shopping_mall_member_orders_create(
    customerConnection,
    {
      body: {
        shopping_mall_customer_address_id: address.id,
      },
    },
  );
  typia.assert(order);
  // 4. Customer creates cancellation request
  const orderItem = order.orderItems[0];
  const cancellationRequest =
    await generate_random_shopping_mall_member_cancellation_requests_create(
      customerConnection,
      {
        body: {
          order_item_id: orderItem.id,
        },
      },
    );
  typia.assert(cancellationRequest);
  // 5. Seller queries snapshots with status='pending' filter
  const pendingSnapshots =
    await api.functional.shoppingMall.seller.cancellation_requests.snapshots.index(
      sellerConnection,
      {
        cancellationRequestId: cancellationRequest.id,
        body: {
          status: "pending",
          page: 1,
          limit: 10,
        } satisfies IShoppingMallCancellationRequestSnapshot.IRequest,
      },
    );
  typia.assert(pendingSnapshots);
  // Verify pending snapshots exist
  TestValidator.predicate(
    "pending snapshots exist",
    () => pendingSnapshots.data.length >= 1,
  );
  TestValidator.predicate("all pending snapshots have pending status", () =>
    pendingSnapshots.data.every((s) => s.status === "pending"),
  );
  // 6. Seller queries snapshots with status='approved' filter
  const approvedSnapshots =
    await api.functional.shoppingMall.seller.cancellation_requests.snapshots.index(
      sellerConnection,
      {
        cancellationRequestId: cancellationRequest.id,
        body: {
          status: "approved",
          page: 1,
          limit: 10,
        } satisfies IShoppingMallCancellationRequestSnapshot.IRequest,
      },
    );
  typia.assert(approvedSnapshots);
  // 7. Seller queries snapshots without status filter
  const allSnapshots =
    await api.functional.shoppingMall.seller.cancellation_requests.snapshots.index(
      sellerConnection,
      {
        cancellationRequestId: cancellationRequest.id,
        body: {
          page: 1,
          limit: 20,
        } satisfies IShoppingMallCancellationRequestSnapshot.IRequest,
      },
    );
  typia.assert(allSnapshots);
  // Verify all snapshots exist and are in chronological order
  TestValidator.predicate(
    "all snapshots exist",
    () => allSnapshots.data.length >= pendingSnapshots.data.length,
  );
  // Verify chronological order by created_at
  if (allSnapshots.data.length > 1) {
    TestValidator.predicate("snapshots in chronological order", () => {
      for (let i = 1; i < allSnapshots.data.length; i++) {
        if (
          new Date(allSnapshots.data[i].createdAt).getTime() <
          new Date(allSnapshots.data[i - 1].createdAt).getTime()
        ) {
          return false;
        }
      }
      return true;
    });
  }
  // 8. Seller queries with pagination parameters
  const paginatedSnapshots =
    await api.functional.shoppingMall.seller.cancellation_requests.snapshots.index(
      sellerConnection,
      {
