  );
  TestValidator.predicate(
    "pagination records match total",
    () =>
      paginatedSnapshots.pagination.records >= paginatedSnapshots.data.length,
  );
  // 9. Seller queries with reviewedAtFrom filter
  const now = new Date();
  const yesterday = new Date(now.getTime() - 24 * 60 * 60 * 1000);
  const tomorrow = new Date(now.getTime() + 24 * 60 * 60 * 1000);
  const timeFilteredSnapshots =
    await api.functional.shoppingMall.seller.cancellation_requests.snapshots.index(
      sellerConnection,
      {
