          reviewedAtTo: tomorrow.toISOString(),
          page: 1,
          limit: 10,
        } satisfies IShoppingMallCancellationRequestSnapshot.IRequest,
      },
    );
  typia.assert(timeFilteredSnapshots);
  // Verify time-filtered snapshots are within range
  TestValidator.predicate("time-filtered snapshots within range", () => {
    for (const snapshot of timeFilteredSnapshots.data) {
      if (snapshot.reviewedAt !== null) {
        const reviewedAt = new Date(snapshot.reviewedAt).getTime();
        if (
          reviewedAt < yesterday.getTime() ||
          reviewedAt > tomorrow.getTime()
        ) {
          return false;
        }
      }
    }
    return true;
  });
  // 10. Verify snapshot references correct cancellation request
  if (allSnapshots.data.length > 0) {
    const firstSnapshot = allSnapshots.data[0];
    TestValidator.predicate(
      "snapshot references correct cancellation request",
      () =>
        firstSnapshot.cancellationRequest !== null &&
        firstSnapshot.cancellationRequest.id === cancellationRequest.id,
    );
