    if (filteredFromResponse.data.length > 0) {
      TestValidator.predicate("reviewedAtFrom filter works", () => {
        return filteredFromResponse.data.every(
          (snapshot) =>
            snapshot.reviewedAt === null ||
            snapshot.reviewedAt >= reviewedAtFrom,
        );
      });
