/**
 * Test administrator retrieval of paginated refund requests list across the platform.
 *
 * Validates that administrators can access all refund requests platform-wide with proper pagination, filtering, and complete summary data including nested member and order item information.
 *
 * The test verifies the complete workflow from admin authentication through refund request listing, ensuring that the admin endpoint returns all refund requests regardless of customer or status, with accurate pagination metadata and proper sorting by creation date.
 *
 * 1. Administrator account created via promotion workflow with authentication.
 * 2. Multiple refund requests created with varying statuses (pending, approved, rejected).
 * 3. Admin retrieves paginated list with default parameters.
 * 4. Validates response structure, pagination accuracy, and data completeness.
 * 5. Confirms nested member and orderItem summaries are properly populated.
 * 6. Verifies sorting order by createdAt descending.
 */
export async function test_api_refund_request_admin_list_all(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create and authenticate administrator
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      grade: RandomGenerator.pick(["regular", "super"] as const),
    } satisfies IShoppingMallAdmin.IJoin,
  });
  // 2. Retrieve refund requests list with default pagination
  const response =
    await api.functional.shoppingMall.admin.refund_requests.index(
      adminConnection,
      {
        body: {
          page: 1,
          limit: 20,
        } satisfies IShoppingMallRefundRequest.IRequest,
      },
    );
  typia.assert(response);
  // 3. Validate pagination metadata
  TestValidator.predicate(
    "pagination current page is 1",
    response.pagination.current === 1,
  );
  TestValidator.predicate(
    "pagination limit is 20",
    response.pagination.limit === 20,
  );
  TestValidator.predicate(
    "pagination records is non-negative",
    response.pagination.records >= 0,
  );
  TestValidator.predicate(
    "pagination pages is non-negative",
    response.pagination.pages >= 0,
  );
  TestValidator.predicate(
    "pages calculation is correct",
    response.pagination.pages ===
      Math.ceil(response.pagination.records / response.pagination.limit),
  );
  // 4. Validate response data is an array
  TestValidator.predicate("data is an array", Array.isArray(response.data));
  // 5. Validate each refund request has required nested structures
  for (const refundRequest of response.data) {
    // Validate member summary exists with required fields
    TestValidator.predicate("member exists", refundRequest.member !== null);
    TestValidator.predicate(
      "member has id",
      refundRequest.member.id !== undefined,
    );
    TestValidator.predicate(
      "member has email",
      refundRequest.member.email !== undefined,
    );
    TestValidator.predicate(
      "member has status",
      refundRequest.member.status !== undefined,
    );
    // Validate orderItem summary exists with required nested objects
    TestValidator.predicate(
      "orderItem exists",
      refundRequest.orderItem !== null,
    );
    TestValidator.predicate(
      "orderItem has id",
      refundRequest.orderItem.id !== undefined,
    );
    TestValidator.predicate(
      "orderItem has quantity",
      refundRequest.orderItem.quantity !== undefined,
    );
    TestValidator.predicate(
      "orderItem has price",
      refundRequest.orderItem.price !== undefined,
    );
    TestValidator.predicate(
      "orderItem has status",
      refundRequest.orderItem.status !== undefined,
    );
    TestValidator.predicate(
      "orderItem has orderCode",
      refundRequest.orderItem.orderCode !== undefined,
    );
    // Validate nested product summary
    TestValidator.predicate(
      "orderItem.product exists",
      refundRequest.orderItem.product !== null,
    );
    TestValidator.predicate(
      "product has id",
      refundRequest.orderItem.product.id !== undefined,
    );
    TestValidator.predicate(
      "product has name",
      refundRequest.orderItem.product.name !== undefined,
    );
    TestValidator.predicate(
      "product has base_price",
      refundRequest.orderItem.product.base_price !== undefined,
    );
    // Validate nested productVariant summary
    TestValidator.predicate(
      "orderItem.productVariant exists",
      refundRequest.orderItem.productVariant !== null,
    );
    TestValidator.predicate(
      "productVariant has id",
      refundRequest.orderItem.productVariant.id !== undefined,
    );
    TestValidator.predicate(
      "productVariant has sku_code",
      refundRequest.orderItem.productVariant.sku_code !== undefined,
    );
    TestValidator.predicate(
      "productVariant has option_values",
      refundRequest.orderItem.productVariant.option_values !== undefined,
    );
    // Validate nested seller summary
    TestValidator.predicate(
      "orderItem.seller exists",
      refundRequest.orderItem.seller !== null,
    );
    TestValidator.predicate(
      "seller has id",
      refundRequest.orderItem.seller.id !== undefined,
    );
    TestValidator.predicate(
      "seller has email",
      refundRequest.orderItem.seller.email !== undefined,
    );
  }
  // 6. Validate sorting by createdAt descending (if multiple records exist)
  if (response.data.length > 1) {
    for (let i = 0; i < response.data.length - 1; i++) {
      const current = new Date(response.data[i].createdAt).getTime();
      const next = new Date(response.data[i + 1].createdAt).getTime();
      TestValidator.predicate(
        `record ${i} should be newer than or equal to record ${i + 1}`,
        current >= next,
      );
    }
  }
}

