/**
 * Test administrator refund request filtering by workflow status.
 *
 * Validates the admin refund requests listing endpoint with status-based filtering capabilities. Tests that administrators can filter refund requests by pending, approved, and rejected statuses, and verifies that omitting the status filter returns all requests regardless of status.
 *
 * The test ensures the filtering mechanism works correctly by calling the endpoint with each status value and validating the response structure. Pagination metadata is verified to accurately reflect the filtered result counts for each query variation.
 *
 * 1. Administrator account created via promotion workflow.
 * 2. Admin queries refund requests with status='pending'.
 * 3. Admin queries refund requests with status='approved'.
 * 4. Admin queries refund requests with status='rejected'.
 * 5. Admin queries refund requests without status filter.
 * 6. Validates response structure and pagination metadata consistency across all filter variations.
 */
export async function test_api_refund_request_admin_filter_by_status(
  connection: api.IConnection,
): Promise<void> {
  // 1. Admin authentication
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      grade: RandomGenerator.pick(["regular", "super"] as const),
    } satisfies IShoppingMallAdmin.IJoin,
  });
  // 2. Test with status='pending'
  const pendingResult =
    await api.functional.shoppingMall.admin.refund_requests.index(
      adminConnection,
      {
        body: {
          status: "pending",
          page: 1,
          limit: 20,
        } satisfies IShoppingMallRefundRequest.IRequest,
      },
    );
  typia.assert(pendingResult);
  // 3. Test with status='approved'
  const approvedResult =
    await api.functional.shoppingMall.admin.refund_requests.index(
      adminConnection,
      {
        body: {
          status: "approved",
          page: 1,
          limit: 20,
        } satisfies IShoppingMallRefundRequest.IRequest,
      },
    );
  typia.assert(approvedResult);
  // 4. Test with status='rejected'
  const rejectedResult =
    await api.functional.shoppingMall.admin.refund_requests.index(
      adminConnection,
      {
        body: {
          status: "rejected",
          page: 1,
          limit: 20,
        } satisfies IShoppingMallRefundRequest.IRequest,
      },
    );
  typia.assert(rejectedResult);
  // 5. Test without status filter (all statuses)
  const allResult =
    await api.functional.shoppingMall.admin.refund_requests.index(
      adminConnection,
      {
        body: {
          page: 1,
          limit: 20,
        } satisfies IShoppingMallRefundRequest.IRequest,
      },
    );
  typia.assert(allResult);
}

