/**
 * Test administrator filtering of refund requests by creation date range.
 *
 * Validates the date range filtering functionality for the admin refund requests listing endpoint. Tests created_at_from parameter for lower bound filtering, created_at_to parameter for upper bound filtering, and combined date range queries. Ensures the API correctly parses ISO 8601 date-time formats and applies inclusive boundary conditions.
 *
 * Note: This test validates the API's filter parameter acceptance and response structure. Actual filtering behavior depends on existing refund request data in the test environment.
 *
 * 1. Administrator authenticates via promotion workflow.
 * 2. Admin queries refund requests with created_at_from filter (7 days ago).
 * 3. Admin queries with created_at_to filter (3 days ago).
 * 4. Admin queries with combined date range (5 days ago to 2 days ago).
 * 5. Admin queries without date filters to retrieve all requests.
 * 6. Validates pagination metadata and response structure for each query.
 */
export async function test_api_refund_request_admin_filter_by_date_range(
  connection: api.IConnection,
): Promise<void> {
  // 1. Admin authentication via promotion workflow
  const adminConnection: api.IConnection = { host: connection.host };
  const adminAuth = await authorize_admin_join(adminConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      grade: RandomGenerator.pick(["regular", "super"] as const),
    } satisfies IShoppingMallAdmin.IJoin,
  });
  typia.assert(adminAuth);
  // 2. Calculate date boundaries for filter testing
  const now = new Date();
  const sevenDaysAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
  const fiveDaysAgo = new Date(now.getTime() - 5 * 24 * 60 * 60 * 1000);
  const threeDaysAgo = new Date(now.getTime() - 3 * 24 * 60 * 60 * 1000);
  const twoDaysAgo = new Date(now.getTime() - 2 * 24 * 60 * 60 * 1000);
  // 3. Test with created_at_from filter (7 days ago)
  const fromResult =
    await api.functional.shoppingMall.admin.refund_requests.index(
      adminConnection,
      {
        body: {
          created_at_from: sevenDaysAgo.toISOString(),
          page: 1,
          limit: 20,
        } satisfies IShoppingMallRefundRequest.IRequest,
      },
    );
  typia.assert(fromResult);
  TestValidator.predicate(
    "from filter pagination valid",
    fromResult.pagination.current >= 1,
  );
  TestValidator.predicate(
    "from filter records non-negative",
    fromResult.pagination.records >= 0,
  );
  // 4. Test with created_at_to filter (3 days ago)
  const toResult =
    await api.functional.shoppingMall.admin.refund_requests.index(
      adminConnection,
      {
        body: {
          created_at_to: threeDaysAgo.toISOString(),
          page: 1,
          limit: 20,
        } satisfies IShoppingMallRefundRequest.IRequest,
      },
    );
  typia.assert(toResult);
  TestValidator.predicate(
    "to filter pagination valid",
    toResult.pagination.current >= 1,
  );
  TestValidator.predicate(
    "to filter records non-negative",
    toResult.pagination.records >= 0,
  );
  // 5. Test with combined date range (5 days ago to 2 days ago)
  const rangeResult =
    await api.functional.shoppingMall.admin.refund_requests.index(
      adminConnection,
      {
        body: {
          created_at_from: fiveDaysAgo.toISOString(),
          created_at_to: twoDaysAgo.toISOString(),
          page: 1,
          limit: 20,
        } satisfies IShoppingMallRefundRequest.IRequest,
      },
    );
  typia.assert(rangeResult);
  TestValidator.predicate(
    "range filter pagination valid",
    rangeResult.pagination.current >= 1,
  );
  TestValidator.predicate(
    "range filter records non-negative",
    rangeResult.pagination.records >= 0,
  );
  // 6. Test without date filters (all requests)
  const allResult =
    await api.functional.shoppingMall.admin.refund_requests.index(
      adminConnection,
      {
        body: {
          page: 1,
          limit: 20,
        } satisfies IShoppingMallRefundRequest.IRequest,
      },
    );
  typia.assert(allResult);
  TestValidator.predicate(
    "all filter pagination valid",
    allResult.pagination.current >= 1,
  );
  TestValidator.predicate(
    "all filter records non-negative",
    allResult.pagination.records >= 0,
  );
  TestValidator.predicate(
    "all filter data is array",
    Array.isArray(allResult.data),
  );
  TestValidator.predicate(
    "all filter pages non-negative",
    allResult.pagination.pages >= 0,
  );
  // 7. Validate response structure consistency across all queries
  TestValidator.predicate(
    "from result has data array",
    Array.isArray(fromResult.data),
  );
  TestValidator.predicate(
    "to result has data array",
    Array.isArray(toResult.data),
  );
  TestValidator.predicate(
    "range result has data array",
    Array.isArray(rangeResult.data),
  );
}

