      },
    );
  typia.assert(rejectedRefundRequest);
  TestValidator.equals(
    "rejected status is correct",
    rejectedRefundRequest.status,
    "rejected",
  );
  TestValidator.predicate(
    "reviewed_at is populated after rejection",
