/**
 * Test refund request creation for a delivered order item.
 *
 * Validates the complete refund request workflow including member authentication, seller product setup, order placement, and refund request submission. Ensures that the refund request is created successfully for a delivered order item with proper status and reason validation.
 *
 * The test covers the e-commerce flow: member joins and authenticates, admin creates a category, seller creates a product with variant, member adds to cart and places order, and member requests a refund for the order item. Note: In a complete environment, shipment creation and delivery confirmation would occur between order placement and refund request.
 *
 * 1. Member customer registers and authenticates.
 * 2. Admin creates a product category.
 * 3. Seller registers and creates product with variant.
 * 4. Member adds variant to cart and places order.
 * 5. Member creates refund request with order_item_id and reason.
 * 6. Validates refund request has 'pending' status and correct order item reference.
 * 7. Validates reason field is non-empty text.
 */
export async function test_api_refund_request_creation_for_delivered_order_item(
  connection: api.IConnection,
): Promise<void> {
  // 1. Member customer registration and authentication
  const memberConnection: api.IConnection = { host: connection.host };
  const memberAuth = await authorize_member_join(memberConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  typia.assert(memberAuth);
  // 2. Admin creates category for product organization
  const adminConnection: api.IConnection = { host: connection.host };
  const adminAuth = await authorize_admin_join(adminConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      grade: "regular" as const,
    },
  });
  typia.assert(adminAuth);
  const category = await api.functional.shoppingMall.admin.categories.create(
    adminConnection,
    {
      body: {
        name: RandomGenerator.paragraph({ sentences: 1 }),
        description: RandomGenerator.content({ paragraphs: 1 }),
      } satisfies IShoppingMallCategory.ICreate,
    },
  );
  typia.assert(category);
  // 3. Seller registration and product creation
  const sellerConnection: api.IConnection = { host: connection.host };
  const sellerAuth = await authorize_seller_join(sellerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  typia.assert(sellerAuth);
  const product = await api.functional.shoppingMall.seller.products.create(
    sellerConnection,
    {
      body: {
        name: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.content({ paragraphs: 2 }),
        shopping_mall_category_id: category.id,
        base_price: typia.random<
          number & tags.Type<"uint32"> & tags.Minimum<1000>
        >(),
      } satisfies IShoppingMallProduct.ICreate,
    },
  );
  typia.assert(product);
  const variant = await api.functional.shoppingMall.seller.variants.create(
    sellerConnection,
    {
      body: {
        shopping_mall_product_id: product.id,
        sku_code: RandomGenerator.alphaNumeric(8),
        option_values: `Color: ${RandomGenerator.pick(["Red", "Blue", "Green"] as const)}, Size: ${RandomGenerator.pick(["S", "M", "L"] as const)}`,
        price: typia.random<
          number & tags.Type<"uint32"> & tags.Minimum<1000>
        >(),
      } satisfies IShoppingMallProductVariant.ICreate,
    },
  );
  typia.assert(variant);
  // 4. Member adds variant to cart and places order
  const cartItem = await api.functional.shoppingMall.member.cart.items.create(
    memberConnection,
    {
      body: {
        product_variant_id: variant.id,
        quantity: typia.random<
          number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<3>
        >(),
      } satisfies IShoppingMallCartItem.ICreate,
    },
  );
  typia.assert(cartItem);
  const address = await api.functional.shoppingMall.member.addresses.create(
    memberConnection,
    {
      body: {
        recipient_name: RandomGenerator.name(),
        recipient_phone: RandomGenerator.mobile(),
        street_address: RandomGenerator.paragraph({ sentences: 1 }),
        city: RandomGenerator.name(),
        state_province: RandomGenerator.name(),
        postal_code: RandomGenerator.alphaNumeric(5),
        country: "United States",
        is_default: true,
      } satisfies IShoppingMallCustomerAddress.ICreate,
    },
  );
  typia.assert(address);
  const order = await api.functional.shoppingMall.member.orders.create(
    memberConnection,
    {
      body: {
        shopping_mall_customer_address_id: address.id,
      } satisfies IShoppingMallOrder.ICreate,
    },
  );
  typia.assert(order);
  // Get the order item from the order
  const orderItem = order.orderItems[0];
  TestValidator.predicate("order item exists", orderItem !== undefined);
  // 5. Member creates refund request for order item
  // Note: In production, the order item must have 'delivered' status.
  // This requires shipment creation and delivery confirmation which are
  // not available in the current SDK function set.
  const refundReason = RandomGenerator.content({
    paragraphs: 1,
    sentenceMin: 2,
    sentenceMax: 4,
  });
  const refundRequest =
    await api.functional.shoppingMall.member.refund_requests.create(
      memberConnection,
      {
        body: {
          order_item_id: orderItem.id,
          reason: refundReason,
        } satisfies IShoppingMallRefundRequest.ICreate,
      },
    );
  typia.assert(refundRequest);
  // 6. Validate refund request
  TestValidator.equals(
    "refund request status is pending",
    refundRequest.status,
    "pending",
  );
  TestValidator.equals(
    "refund request order item matches",
    refundRequest.orderItem.id,
    orderItem.id,
  );
  TestValidator.predicate(
    "refund request reason is non-empty",
    refundRequest.reason.length > 0,
  );
  TestValidator.equals(
    "refund request reason matches input",
    refundRequest.reason,
    refundReason,
  );
  TestValidator.predicate(
    "refund request has created_at",
    refundRequest.created_at !== undefined,
  );
  TestValidator.equals(
    "refund request reviewed_at is null",
    refundRequest.reviewed_at,
    null,
  );
  TestValidator.equals(
    "refund request member matches",
    refundRequest.member.id,
    memberAuth.id,
  );
  TestValidator.predicate(
    "refund request deleted_at is null",
    refundRequest.deleted_at === null,
  );
}

