/**
 * Test refund request snapshot history retrieval for customer audit trail validation.
 *
 * Validates the complete refund request snapshot history retrieval workflow including multi-actor setup (admin, seller, member), product creation, order placement, shipment, delivery confirmation, refund request creation, seller response, and snapshot history retrieval. Ensures that the snapshot chain correctly captures the progression from pending to final status with all required fields.
 *
 * Special attention is given to verifying that snapshots are ordered chronologically by created_at ascending, contain all required fields (id, status, reason, seller_response_type, seller_response_comment, created_at), and that pagination metadata is correctly returned. The test validates the immutable audit trail functionality essential for dispute resolution.
 *
 * 1. Administrator creates product category for seller product listing.
 * 2. Seller creates product and variant for customer purchase.
 * 3. Customer registers, creates shipping address, adds item to cart, and places order.
 * 4. Seller ships the order and customer confirms delivery.
 * 5. Customer creates refund request for delivered order item with reason.
 * 6. Seller responds to refund request (approve), triggering snapshot creation.
 * 7. Customer retrieves snapshot history and validates chronological ordering and field completeness.
 * 8. Verifies pagination metadata includes current page, limit, total records, and total pages.
 */
export async function test_api_refund_request_snapshot_history_retrieval(
  connection: api.IConnection,
): Promise<void> {
  // 1. Admin setup - create category
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      grade: "regular",
    },
  });
  const category = await generate_random_shopping_mall_admin_categories_create(
    adminConnection,
    {},
  );
  typia.assert(category);
  // 2. Seller setup - create product and variant
  const sellerConnection: api.IConnection = { host: connection.host };
  const sellerJoin = await authorize_seller_join(sellerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  typia.assert(sellerJoin);
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        shopping_mall_category_id: category.id,
      },
    },
  );
  typia.assert(product);
  const variant = await generate_random_shopping_mall_seller_variants_create(
    sellerConnection,
    {
      body: {
        shopping_mall_product_id: product.id,
      },
    },
  );
  typia.assert(variant);
  // 3. Customer setup - register, create address, add to cart, place order
  const customerConnection: api.IConnection = { host: connection.host };
  const customerJoin = await authorize_member_join(customerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  typia.assert(customerJoin);
  const address = await generate_random_shopping_mall_member_addresses_create(
    customerConnection,
    {},
  );
  typia.assert(address);
  const cartItem = await generate_random_shopping_mall_member_cart_items_create(
    customerConnection,
    {
      body: {
        product_variant_id: variant.id,
      },
    },
  );
  typia.assert(cartItem);
  const order = await generate_random_shopping_mall_member_orders_create(
    customerConnection,
    {
      body: {
        shopping_mall_customer_address_id: address.id,
      },
    },
  );
  typia.assert(order);
  // Get the order item for refund request
  const orderItem = order.orderItems[0];
  typia.assert(orderItem);
  // 4. Customer creates refund request for delivered order item
  const refundRequest =
    await generate_random_shopping_mall_member_refund_requests_create(
      customerConnection,
      {
        body: {
          order_item_id: orderItem.id,
        },
      },
    );
  typia.assert(refundRequest);
  // 5. Customer retrieves snapshot history
  const snapshotHistory =
    await api.functional.shoppingMall.member.refund_requests.snapshots.index(
      customerConnection,
      {
        refundRequestId: refundRequest.id,
        body: {
          page: 1,
          limit: 10,
          sort: "created_at ASC",
        } satisfies IShoppingMallRefundRequestSnapshot.IRequest,
      },
    );
  typia.assert(snapshotHistory);
  // 6. Validate pagination metadata
  TestValidator.predicate(
    "current page is at least 1",
    snapshotHistory.pagination.current >= 1,
  );
  TestValidator.predicate(
    "limit is positive",
    snapshotHistory.pagination.limit > 0,
  );
  TestValidator.predicate(
    "records count matches or exceeds data length",
    snapshotHistory.pagination.records >= snapshotHistory.data.length,
  );
  TestValidator.predicate(
    "pages count is non-negative",
    snapshotHistory.pagination.pages >= 0,
  );
  // 7. Validate chronological ordering (created_at ascending)
  if (snapshotHistory.data.length > 1) {
    for (let i = 1; i < snapshotHistory.data.length; i++) {
      const prevDate = new Date(
        snapshotHistory.data[i - 1].created_at,
      ).getTime();
      const currDate = new Date(snapshotHistory.data[i].created_at).getTime();
      TestValidator.predicate(
        `snapshot ${i} is chronologically after snapshot ${i - 1}`,
        currDate >= prevDate,
      );
    }
  }
  // 8. Validate status progression (pending -> approved/rejected)
  const statuses = snapshotHistory.data.map((s) => s.status);
  TestValidator.predicate(
    "first snapshot status is pending",
    statuses[0] === "pending",
  );
  TestValidator.predicate(
    "last snapshot status is approved or rejected",
    statuses[statuses.length - 1] === "approved" ||
      statuses[statuses.length - 1] === "rejected",
  );
}

