/**
 * Test refund request snapshot status filtering functionality for sellers.
 *
 * Validates the complete refund request snapshot filtering workflow including status-based filtering, date range filtering, pagination, and sorting. The test creates a realistic scenario where a customer requests a refund and the seller responds, generating multiple snapshots that can be filtered and queried.
 *
 * The test verifies that sellers can effectively navigate refund request history by filtering snapshots based on status (pending, approved, rejected), viewing snapshots from specific time periods, and controlling result ordering through pagination and sort parameters.
 *
 * 1. Administrator creates a product category for product organization.
 * 2. Seller registers account and creates a product with variant.
 * 3. Customer registers, creates shipping address, adds variant to cart, and places order.
 * 4. Customer creates a refund request for the delivered order item.
 * 5. Seller retrieves snapshots filtered by status='pending' and validates results.
 * 6. Seller retrieves snapshots filtered by status='approved' or 'rejected' and validates results.
 * 7. Seller retrieves snapshots with date range filters and validates temporal boundaries.
 * 8. Seller validates pagination parameters (page, limit) return correct subsets.
 * 9. Seller validates sort parameter orders results by created_at ASC and DESC.
 */
export async function test_api_refund_request_snapshot_status_filtering(
  connection: api.IConnection,
): Promise<void> {
  // 1. Admin creates category
  const adminPassword = RandomGenerator.alphaNumeric(16);
  const adminJoinResult = await authorize_admin_join(
    { host: connection.host },
    {
      body: {
        password: adminPassword,
      },
    },
  );
  typia.assert(adminJoinResult);
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_login(adminConnection, {
    body: {
      email: adminJoinResult.email,
      password: adminPassword,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: typia.random<string & tags.Format<"ipv4">>(),
    } satisfies IShoppingMallAdmin.ILogin,
  });
  const category = await generate_random_shopping_mall_admin_categories_create(
    adminConnection,
    {},
  );
  typia.assert(category);
  // 2. Seller registers and creates product
  const sellerPassword = RandomGenerator.alphaNumeric(16);
  const sellerJoinResult = await authorize_seller_join(
    { host: connection.host },
    {
      body: {
        password: sellerPassword,
      },
    },
  );
  typia.assert(sellerJoinResult);
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_login(sellerConnection, {
    body: {
      email: sellerJoinResult.email,
      password: sellerPassword,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: typia.random<string & tags.Format<"ipv4">>(),
    } satisfies IShoppingMallSeller.ILogin,
  });
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        shopping_mall_category_id: category.id,
      },
    },
  );
  typia.assert(product);
  const variant = await generate_random_shopping_mall_seller_variants_create(
    sellerConnection,
    {
      body: {
        shopping_mall_product_id: product.id,
      },
    },
  );
  typia.assert(variant);
  // 3. Customer registers, creates address, adds to cart, places order
  const customerPassword = RandomGenerator.alphaNumeric(16);
  const customerJoinResult = await authorize_member_join(
    { host: connection.host },
    {
      body: {
        password: customerPassword,
      },
    },
  );
  typia.assert(customerJoinResult);
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_member_login(customerConnection, {
    body: {
      email: customerJoinResult.email,
      password: customerPassword,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: typia.random<string & tags.Format<"ipv4">>(),
    } satisfies IShoppingMallMember.ILogin,
  });
  const address = await generate_random_shopping_mall_member_addresses_create(
    customerConnection,
    {},
  );
  typia.assert(address);
  const cartItem = await generate_random_shopping_mall_member_cart_items_create(
    customerConnection,
    {
      body: {
        product_variant_id: variant.id,
      },
    },
  );
  typia.assert(cartItem);
  const order = await generate_random_shopping_mall_member_orders_create(
    customerConnection,
    {
      body: {
        shopping_mall_customer_address_id: address.id,
      },
    },
  );
  typia.assert(order);
  // 4. Customer creates refund request for order item
  const orderItem = order.orderItems[0];
  const refundRequest =
    await generate_random_shopping_mall_member_refund_requests_create(
      customerConnection,
      {
        body: {
          order_item_id: orderItem.id,
        },
      },
    );
  typia.assert(refundRequest);
  // 5. Test status filtering - pending
  const pendingSnapshots =
    await api.functional.shoppingMall.seller.refund_requests.snapshots.index(
      sellerConnection,
      {
        refundRequestId: refundRequest.id,
        body: {
          status: "pending",
          page: 1,
          limit: 10,
          sort: "created_at ASC",
        } satisfies IShoppingMallRefundRequestSnapshot.IRequest,
      },
    );
  typia.assert(pendingSnapshots);
  TestValidator.predicate(
    "pending snapshots returned",
    pendingSnapshots.data.length >= 0,
  );
  pendingSnapshots.data.forEach((snapshot) => {
    TestValidator.equals("status is pending", snapshot.status, "pending");
  });
  // 6. Test status filtering - approved/rejected
  const allSnapshots =
    await api.functional.shoppingMall.seller.refund_requests.snapshots.index(
      sellerConnection,
      {
        refundRequestId: refundRequest.id,
        body: {
          page: 1,
          limit: 100,
        } satisfies IShoppingMallRefundRequestSnapshot.IRequest,
      },
    );
  typia.assert(allSnapshots);
  const nonPendingStatus =
    allSnapshots.data.find((s) => s.status !== "pending")?.status ?? "approved";
  const statusFilteredSnapshots =
    await api.functional.shoppingMall.seller.refund_requests.snapshots.index(
      sellerConnection,
      {
        refundRequestId: refundRequest.id,
        body: {
          status: nonPendingStatus,
          page: 1,
          limit: 10,
        } satisfies IShoppingMallRefundRequestSnapshot.IRequest,
      },
    );
  typia.assert(statusFilteredSnapshots);
  statusFilteredSnapshots.data.forEach((snapshot) => {
    TestValidator.equals(
      "status matches filter",
      snapshot.status,
      nonPendingStatus,
    );
  });
  // 7. Test date range filtering
  const now = new Date();
  const yesterday = new Date(now.getTime() - 24 * 60 * 60 * 1000);
  const tomorrow = new Date(now.getTime() + 24 * 60 * 60 * 1000);
  const dateRangeSnapshots =
    await api.functional.shoppingMall.seller.refund_requests.snapshots.index(
      sellerConnection,
      {
        refundRequestId: refundRequest.id,
        body: {
          created_at_from: yesterday.toISOString(),
          created_at_to: tomorrow.toISOString(),
          page: 1,
          limit: 10,
        } satisfies IShoppingMallRefundRequestSnapshot.IRequest,
      },
    );
  typia.assert(dateRangeSnapshots);
  dateRangeSnapshots.data.forEach((snapshot) => {
    const snapshotDate = new Date(snapshot.created_at);
    TestValidator.predicate(
      "snapshot within date range",
      snapshotDate >= yesterday && snapshotDate <= tomorrow,
    );
  });
  // 8. Test pagination
  const page1Snapshots =
    await api.functional.shoppingMall.seller.refund_requests.snapshots.index(
      sellerConnection,
      {
        refundRequestId: refundRequest.id,
        body: {
          page: 1,
          limit: 1,
        } satisfies IShoppingMallRefundRequestSnapshot.IRequest,
      },
    );
  typia.assert(page1Snapshots);
  TestValidator.predicate(
    "page 1 limit 1 returns at most 1 item",
    page1Snapshots.data.length <= 1,
  );
  TestValidator.equals(
    "pagination current page",
    page1Snapshots.pagination.current,
    1,
  );
  // 9. Test sorting
  const sortedAscSnapshots =
    await api.functional.shoppingMall.seller.refund_requests.snapshots.index(
      sellerConnection,
      {
        refundRequestId: refundRequest.id,
        body: {
          sort: "created_at ASC",
          page: 1,
          limit: 10,
        } satisfies IShoppingMallRefundRequestSnapshot.IRequest,
      },
    );
  typia.assert(sortedAscSnapshots);
  for (let i = 1; i < sortedAscSnapshots.data.length; i++) {
    const prevDate = new Date(sortedAscSnapshots.data[i - 1].created_at);
    const currDate = new Date(sortedAscSnapshots.data[i].created_at);
    TestValidator.predicate(
      "ASC order maintained",
      prevDate.getTime() <= currDate.getTime(),
    );
  }
  const sortedDescSnapshots =
    await api.functional.shoppingMall.seller.refund_requests.snapshots.index(
      sellerConnection,
      {
        refundRequestId: refundRequest.id,
        body: {
          sort: "created_at DESC",
          page: 1,
          limit: 10,
        } satisfies IShoppingMallRefundRequestSnapshot.IRequest,
      },
    );
  typia.assert(sortedDescSnapshots);
  for (let i = 1; i < sortedDescSnapshots.data.length; i++) {
    const prevDate = new Date(sortedDescSnapshots.data[i - 1].created_at);
    const currDate = new Date(sortedDescSnapshots.data[i].created_at);
    TestValidator.predicate(
      "DESC order maintained",
      prevDate.getTime() >= currDate.getTime(),
    );
  }
}

