/**
 * Test refund request snapshot history retrieval for a delivered order item.
 *
 * Validates the complete refund request snapshot history retrieval workflow including administrative category setup, seller product creation, member order placement, shipment delivery, refund request creation, and snapshot history retrieval. Ensures that the snapshot history correctly captures the initial pending state with customer's reason and null seller_response.
 *
 * Special attention is given to verifying that the snapshot history contains at least one snapshot (the initial pending state), snapshots are ordered chronologically by created_at ASC, and each snapshot preserves the exact state at submission time including status, reason, and seller_response fields.
 *
 * 1. Administrator creates a product category for product organization.
 * 2. Seller registers and creates a product with variant for purchase.
 * 3. Member registers, creates shipping address, adds item to cart, and places order.
 * 4. Seller creates shipment and marks order as delivered by setting delivered_at.
 * 5. Member creates a refund request for the delivered order item.
 * 6. Member retrieves snapshot history for the refund request.
 * 7. Validates snapshot history contains at least one snapshot with correct structure and chronological ordering.
 */
export async function test_api_refund_request_snapshot_history_retrieval(
  connection: api.IConnection,
): Promise<void> {
  // 1. Admin setup - create category
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_login(adminConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IShoppingMallAdmin.ILogin,
  });
  const category = await generate_random_shopping_mall_admin_categories_create(
    adminConnection,
    {},
  );
  typia.assert(category);
  // 2. Seller setup - register and create product with variant
  const sellerConnection: api.IConnection = { host: connection.host };
  const sellerJoin = await authorize_seller_join(sellerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IShoppingMallSeller.IJoin,
  });
  typia.assert(sellerJoin);
  await authorize_seller_login(sellerConnection, {
    body: {
      email: sellerJoin.email,
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IShoppingMallSeller.ILogin,
  });
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        shopping_mall_category_id: category.id,
      },
    },
  );
  typia.assert(product);
  const variant = await generate_random_shopping_mall_seller_variants_create(
    sellerConnection,
    {
      body: {
        shopping_mall_product_id: product.id,
      },
    },
  );
  typia.assert(variant);
  // 3. Member setup - register, create address, add to cart, place order
  const memberConnection: api.IConnection = { host: connection.host };
  const memberJoin = await authorize_member_join(memberConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IShoppingMallMember.IJoin,
  });
  typia.assert(memberJoin);
  const address = await generate_random_shopping_mall_member_addresses_create(
    memberConnection,
    {},
  );
  typia.assert(address);
  const cartItem = await generate_random_shopping_mall_member_cart_items_create(
    memberConnection,
    {
      body: {
        product_variant_id: variant.id,
      },
    },
  );
  typia.assert(cartItem);
  const order = await generate_random_shopping_mall_member_orders_create(
    memberConnection,
    {
      body: {
        shopping_mall_customer_address_id: address.id,
      },
    },
  );
  typia.assert(order);
  // 4. Seller creates shipment to mark order as delivered
  const orderItem = order.orderItems[0];
  TestValidator.predicate("order item exists", orderItem !== undefined);
  const shipment =
    await generate_random_shopping_mall_seller_orders_shipments_create(
      sellerConnection,
      {
        params: { orderId: order.id },
        body: {
          order_item_ids: [orderItem.id],
        },
      },
    );
  typia.assert(shipment);
  // 5. Member creates refund request for delivered order item
  const refundRequest =
    await generate_random_shopping_mall_member_post_purchase_refund_requests_create(
      memberConnection,
      {
        body: {
          order_item_id: orderItem.id,
        },
      },
    );
  typia.assert(refundRequest);
  // 6. Member retrieves snapshot history for the refund request
  const snapshotHistory =
    await api.functional.shoppingMall.member.post_purchase.refund_requests.snapshots.index(
      memberConnection,
      {
        refundRequestId: refundRequest.id,
        body: {
          page: 1,
          limit: 20,
          sort: "asc",
        } satisfies IShoppingMallPostPurchaseRefundRequestSnapshot.IRequest,
      },
    );
  typia.assert(snapshotHistory);
  // 7. Validate snapshot history
  TestValidator.predicate(
    "has at least one snapshot",
    snapshotHistory.data.length >= 1,
  );
  TestValidator.equals(
    "pagination current page",
    snapshotHistory.pagination.current,
    1,
  );
  TestValidator.predicate(
    "pagination records match data length",
    snapshotHistory.pagination.records >= snapshotHistory.data.length,
  );
  // Validate first snapshot (initial pending state)
  const firstSnapshot = snapshotHistory.data[0];
  TestValidator.equals(
    "first snapshot status is pending",
    firstSnapshot.status,
    "pending",
  );
  TestValidator.predicate(
    "first snapshot has reason",
    firstSnapshot.reason !== undefined && firstSnapshot.reason.length > 0,
  );
  TestValidator.equals(
    "first snapshot seller_response is null",
    firstSnapshot.seller_response,
    null,
  );
  TestValidator.predicate(
    "first snapshot has created_at",
    firstSnapshot.created_at !== undefined,
  );
  // Validate snapshot ordering (chronological ASC)
  if (snapshotHistory.data.length > 1) {
    for (let i = 1; i < snapshotHistory.data.length; i++) {
      const prevTime = new Date(
        snapshotHistory.data[i - 1].created_at,
      ).getTime();
      const currTime = new Date(snapshotHistory.data[i].created_at).getTime();
      TestValidator.predicate(
        `snapshot ${i} is after snapshot ${i - 1}`,
        currTime >= prevTime,
      );
    }
  }
  // Validate refundRequest reference in snapshot
  TestValidator.equals(
    "snapshot refundRequest id matches",
    firstSnapshot.refundRequest.id,
    refundRequest.id,
  );
  TestValidator.equals(
    "snapshot refundRequest status matches",
    firstSnapshot.refundRequest.status,
    refundRequest.status,
  );
}

