/**
 * Test filtering refund request snapshots by status to verify pagination and filter functionality.
 *
 * Validates the complete refund request snapshot history retrieval with status filtering. Tests that snapshots are correctly filtered by workflow status (pending, approved), pagination metadata accurately reflects filtered counts, and chronological ordering is maintained regardless of filter applied.
 *
 * The test establishes a complete e-commerce workflow: admin creates category, seller creates product and variant, member places order, seller ships and delivers, member requests refund, and seller approves. This creates two snapshots: initial pending state and approved state after seller response.
 *
 * 1. Administrator creates category for product organization.
 * 2. Seller creates product listing with variant.
 * 3. Member creates address, adds to cart, places order.
 * 4. Seller creates shipment to mark order as delivered.
 * 5. Member creates refund request (creates pending snapshot).
 * 6. Seller approves refund request (creates approved snapshot).
 * 7. Member retrieves snapshots filtered by status='pending' - expects 1 snapshot.
 * 8. Member retrieves snapshots filtered by status='approved' - expects 1 snapshot.
 * 9. Member retrieves all snapshots without filter - expects 2 snapshots in chronological order.
 * 10. Validates pagination metadata, status values, seller_response population, and ordering.
 */
export async function test_api_refund_request_snapshot_status_filtering(
  connection: api.IConnection,
): Promise<void> {
  // 1. Admin setup - create category
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      grade: "regular" as const,
    },
  });
  const category =
    await generate_random_shopping_mall_admin_categories_create(
      adminConnection,
      {},
    );
  typia.assert(category);
  // 2. Seller setup - create product and variant
  const sellerConnection: api.IConnection = { host: connection.host };
  const sellerAuth = await authorize_seller_join(sellerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  typia.assert(sellerAuth);
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        shopping_mall_category_id: category.id,
      },
    },
  );
  typia.assert(product);
  const variant = await generate_random_shopping_mall_seller_variants_create(
    sellerConnection,
    {
      body: {
        shopping_mall_product_id: product.id,
      },
    },
  );
  typia.assert(variant);
  // 3. Member setup - create account, address, cart, order
  const memberConnection: api.IConnection = { host: connection.host };
  const memberAuth = await authorize_member_join(memberConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  typia.assert(memberAuth);
  const address =
    await generate_random_shopping_mall_member_addresses_create(
      memberConnection,
      {},
    );
  typia.assert(address);
  const cartItem = await generate_random_shopping_mall_member_cart_items_create(
    memberConnection,
    {
      body: {
        product_variant_id: variant.id,
      },
    },
  );
  typia.assert(cartItem);
  const order = await generate_random_shopping_mall_member_orders_create(
    memberConnection,
    {
      body: {
        shopping_mall_customer_address_id: address.id,
      },
    },
  );
  typia.assert(order);
  // 4. Seller creates shipment to deliver order
  const orderItemId = order.orderItems[0]?.id;
  if (!orderItemId) {
    throw new Error("Order must have at least one order item");
  }
  const shipment =
    await generate_random_shopping_mall_seller_orders_shipments_create(
      sellerConnection,
      {
        body: {
          order_item_ids: [orderItemId],
        },
        params: {
          orderId: order.id,
        },
      },
    );
  typia.assert(shipment);
  // 5. Member creates refund request
  const refundRequest =
    await generate_random_shopping_mall_member_post_purchase_refund_requests_create(
      memberConnection,
      {
        body: {
          order_item_id: orderItemId,
        },
      },
    );
  typia.assert(refundRequest);
  // 6. Seller approves refund request
  const approvedRefundRequest =
    await api.functional.shoppingMall.seller.refund_requests.approve(
      sellerConnection,
      {
        refundRequestId: refundRequest.id,
      },
    );
  typia.assert(approvedRefundRequest);
  // 7. Test filtering by status='pending'
  const pendingSnapshots =
    await api.functional.shoppingMall.member.post_purchase.refund_requests.snapshots.index(
      memberConnection,
      {
        refundRequestId: refundRequest.id,
        body: {
          status: "pending",
          sort: "asc",
          page: 1,
          limit: 10,
        },
      },
    );
  typia.assert(pendingSnapshots);
  TestValidator.equals(
    "pending filter returns 1 snapshot",
    pendingSnapshots.data.length,
    1,
  );
  TestValidator.equals(
    "pending snapshot has pending status",
    pendingSnapshots.data[0]?.status,
    "pending",
  );
  TestValidator.predicate(
    "pending snapshot has null seller_response",
    pendingSnapshots.data[0]?.seller_response === null,
  );
  TestValidator.equals(
    "pending pagination records count",
    pendingSnapshots.pagination.records,
    1,
  );
  // 8. Test filtering by status='approved'
  const approvedSnapshots =
    await api.functional.shoppingMall.member.post_purchase.refund_requests.snapshots.index(
      memberConnection,
      {
        refundRequestId: refundRequest.id,
        body: {
          status: "approved",
          sort: "asc",
          page: 1,
          limit: 10,
        },
      },
    );
  typia.assert(approvedSnapshots);
  TestValidator.equals(
    "approved filter returns 1 snapshot",
    approvedSnapshots.data.length,
    1,
  );
  TestValidator.equals(
    "approved snapshot has approved status",
    approvedSnapshots.data[0]?.status,
    "approved",
  );
  TestValidator.predicate(
    "approved snapshot has seller_response",
    approvedSnapshots.data[0]?.seller_response !== null,
  );
  TestValidator.equals(
    "approved pagination records count",
    approvedSnapshots.pagination.records,
    1,
  );
  // 9. Test without status filter (all snapshots)
  const allSnapshots =
    await api.functional.shoppingMall.member.post_purchase.refund_requests.snapshots.index(
      memberConnection,
      {
        refundRequestId: refundRequest.id,
        body: {
          sort: "asc",
          page: 1,
          limit: 10,
        },
      },
    );
  typia.assert(allSnapshots);
  TestValidator.equals(
    "all snapshots returns 2 snapshots",
    allSnapshots.data.length,
    2,
  );
  TestValidator.equals(
    "all snapshots pagination records count",
    allSnapshots.pagination.records,
    2,
  );
  // 10. Validate chronological ordering
  const firstSnapshot = allSnapshots.data[0];
  const secondSnapshot = allSnapshots.data[1];
  TestValidator.equals(
    "first snapshot is pending",
    firstSnapshot?.status,
    "pending",
  );
  TestValidator.equals(
    "second snapshot is approved",
    secondSnapshot?.status,
    "approved",
  );
  TestValidator.predicate(
    "chronological order maintained",
    new Date(firstSnapshot?.created_at ?? "").getTime() <=
      new Date(secondSnapshot?.created_at ?? "").getTime(),
  );
  // 11. Validate seller_response population
  TestValidator.predicate(
    "pending snapshot has null seller_response",
    firstSnapshot?.seller_response === null,
  );
  TestValidator.predicate(
    "approved snapshot has seller_response",
    secondSnapshot?.seller_response !== null,
  );
}

