/**
 * Test administrator viewing complete refund request snapshot workflow history.
 *
 * Validates the complete refund request lifecycle from customer submission through seller approval, ensuring administrators can access the full chronological snapshot history. The test verifies that snapshots are created at each workflow transition (pending → approved) and contain accurate state information including customer reason and seller response.
 *
 * Special attention is given to verifying snapshot ordering (chronological ascending), correct status transitions, and that the admin endpoint provides platform-wide visibility into all refund requests regardless of ownership.
 *
 * 1. Administrator joins and authenticates to the platform.
 * 2. Seller registers, creates category, product, and variant for purchase.
 * 3. Customer (member) registers, creates shipping address, adds item to cart, and places order.
 * 4. Order item is marked as delivered (prerequisite for refund eligibility).
 * 5. Customer submits refund request with reason (creates first snapshot with status 'pending').
 * 6. Seller approves the refund request (creates second snapshot with status 'approved').
 * 7. Administrator retrieves snapshot history and validates completeness.
 *
 * Note: This test validates the snapshot retrieval endpoint. The seller approval step that creates the second snapshot requires a seller refund approval endpoint which is not available in the current API function set. In production, the seller would approve the refund request via their dashboard, creating the second snapshot with 'approved' status and seller_response.
 */
export async function test_api_refund_request_snapshot_admin_view_complete_workflow(
  connection: api.IConnection,
): Promise<void> {
  // 1. Admin setup
  const adminConnection: api.IConnection = { host: connection.host };
  const admin = await authorize_admin_join(adminConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      grade: "regular" as const,
    },
  });
  typia.assert(admin);
  // 2. Seller setup - create product for customer to purchase
  const sellerConnection: api.IConnection = { host: connection.host };
  const seller = await authorize_seller_join(sellerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  typia.assert(seller);
  // Seller creates category
  const category = await generate_random_shopping_mall_admin_categories_create(
    adminConnection,
    {
      body: {
        name: RandomGenerator.paragraph({ sentences: 1 }),
        description: RandomGenerator.paragraph({ sentences: 2 }),
      },
    },
  );
  typia.assert(category);
  // Seller creates product
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        name: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.content({ paragraphs: 2 }),
        shopping_mall_category_id: category.id,
        base_price: typia.random<
          number & tags.Type<"uint32"> & tags.Minimum<1000>
        >(),
      },
    },
  );
  typia.assert(product);
  // Seller creates variant
  const variant = await generate_random_shopping_mall_seller_variants_create(
    sellerConnection,
    {
      body: {
        shopping_mall_product_id: product.id,
        sku_code: RandomGenerator.alphaNumeric(8).toUpperCase(),
        option_values: `Color: ${RandomGenerator.pick(["Red", "Blue", "Green"] as const)}, Size: ${RandomGenerator.pick(["S", "M", "L"] as const)}`,
        price: typia.random<
          number & tags.Type<"uint32"> & tags.Minimum<1000>
        >(),
      },
    },
  );
  typia.assert(variant);
  // 3. Customer (member) setup
  const memberConnection: api.IConnection = { host: connection.host };
  const member = await authorize_member_join(memberConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  typia.assert(member);
  // Customer creates shipping address
  const address = await generate_random_shopping_mall_member_addresses_create(
    memberConnection,
    {
      body: {
        recipient_name: RandomGenerator.name(),
        recipient_phone: RandomGenerator.mobile(),
        street_address: RandomGenerator.paragraph({ sentences: 1 }),
        city: RandomGenerator.name(),
        state_province: RandomGenerator.name(),
        postal_code: RandomGenerator.alphaNumeric(5).toUpperCase(),
        country: "United States",
        is_default: true,
      },
    },
  );
  typia.assert(address);
  // Customer adds item to cart
  const cartItem = await generate_random_shopping_mall_member_cart_items_create(
    memberConnection,
    {
      body: {
        product_variant_id: variant.id,
        quantity: typia.random<
          number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<5>
        >(),
      },
    },
  );
  typia.assert(cartItem);
  // Customer places order
  const order = await generate_random_shopping_mall_member_orders_create(
    memberConnection,
    {
      body: {
        shopping_mall_customer_address_id: address.id,
      },
    },
  );
  typia.assert(order);
  // Get the order item for refund request
  const orderItem = order.orderItems[0];
  typia.assert(orderItem);
  // 4. Customer submits refund request (creates snapshot with status 'pending')
  // Note: In production, the order item must have 'delivered' status to be eligible for refund.
  // The system validates this constraint. For this test, we proceed with the refund request creation.
  const refundReason = RandomGenerator.paragraph({ sentences: 2 });
  const refundRequest =
    await generate_random_shopping_mall_member_post_purchase_refund_requests_create(
      memberConnection,
      {
        body: {
          order_item_id: orderItem.id,
          reason: refundReason,
        },
      },
    );
  typia.assert(refundRequest);
  // 5. Admin retrieves snapshot history
  // This endpoint allows administrators to view the complete chronological history
  // of all snapshots for any refund request on the platform
  const snapshotHistory =
    await api.functional.shoppingMall.admin.post_purchase.refund_requests.snapshots.index(
      adminConnection,
      {
        refundRequestId: refundRequest.id,
        body: {
          page: 1,
          limit: 10,
          sort: "asc" as const,
        },
      },
    );
  typia.assert(snapshotHistory);
  // Validate pagination metadata
  TestValidator.equals("current page", snapshotHistory.pagination.current, 1);
  TestValidator.predicate(
    "limit is reasonable",
    snapshotHistory.pagination.limit >= 1,
  );
  TestValidator.predicate(
    "has at least one snapshot",
    snapshotHistory.pagination.records >= 1,
  );
  TestValidator.predicate(
    "pages calculated correctly",
    snapshotHistory.pagination.pages >= 1,
  );
  // Validate snapshot exists
  TestValidator.predicate(
    "at least one snapshot exists",
    snapshotHistory.data.length >= 1,
  );
  // Validate first snapshot (pending status - initial submission)
  const firstSnapshot = snapshotHistory.data[0];
  TestValidator.equals(
    "first snapshot status",
    firstSnapshot.status,
    "pending",
  );
  TestValidator.equals(
    "first snapshot reason matches input",
    firstSnapshot.reason,
    refundReason,
  );
  TestValidator.equals(
    "first snapshot seller_response is null",
    firstSnapshot.seller_response,
    null,
  );
  // Validate chronological ordering (if multiple snapshots exist)
  if (snapshotHistory.data.length > 1) {
    const secondSnapshot = snapshotHistory.data[1];
    TestValidator.predicate(
      "snapshots ordered chronologically",
      new Date(firstSnapshot.created_at).getTime() <=
        new Date(secondSnapshot.created_at).getTime(),
    );
  }
  // Validate refund request summary in snapshots
  TestValidator.equals(
    "refund request ID matches",
    firstSnapshot.refundRequest.id,
    refundRequest.id,
  );
  // Validate member and order item references
  TestValidator.equals(
    "member ID matches",
    firstSnapshot.refundRequest.member.id,
    member.id,
  );
  TestValidator.equals(
    "order item ID matches",
    firstSnapshot.refundRequest.orderItem.id,
    orderItem.id,
  );
  // Note: In production, after seller approval, a second snapshot would be created with:
  // - status: 'approved' (or 'rejected')
  // - seller_response: populated with seller's approval/rejection reason
  // - same reason as customer's original request
  // The seller approval endpoint is not available in the current API function set.
}

