  // 4. Seller retrieves review snapshots (should be empty since review was never edited)
  const snapshotsResponse =
    await api.functional.shoppingMall.seller.reviews.snapshots.index(
      sellerConnection,
      {
        reviewId: review.id,
        body: {
          page: 1,
          limit: 10,
