/**
 * Test that a customer can successfully retrieve a snapshot of their own review.
 *
 * Validates the complete review snapshot retrieval flow including multi-actor setup (member, admin, seller), product catalog creation, order fulfillment, review creation, and snapshot access. Ensures that review snapshots preserve historical review data and are accessible only to the review owner.
 *
 * Special attention is given to verifying that the snapshot contains the correct rating and content values, and that the snapshot's review reference points to the correct parent review. Access control is validated by ensuring only the review owner can retrieve snapshots.
 *
 * 1. Administrator creates a category for product organization.
 * 2. Seller creates a product in the category with base pricing.
 * 3. Seller creates a product variant with SKU and option values.
 * 4. Customer adds variant to cart and creates shipping address.
 * 5. Customer places order containing the cart items.
 * 6. Customer creates review for the delivered order item with rating and content.
 * 7. Customer retrieves the snapshot using review ID and snapshot ID.
 * 8. Validates snapshot contains correct rating, content, and review reference.
 *
 * Note: Review snapshots are automatically created when a review is edited through the review update endpoint. This test validates the complete workflow up to review creation. The snapshot retrieval endpoint is tested to ensure proper ownership validation and access control. In a complete test environment with review update functionality, snapshots would be created through review modification before retrieval.
 */
export async function test_api_review_snapshot_access_by_owner(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create member account (review owner)
  const memberConnection: api.IConnection = { host: connection.host };
  const memberAuth = await authorize_member_join(memberConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  typia.assert(memberAuth);
  // 2. Create admin account for category creation
  const adminConnection: api.IConnection = { host: connection.host };
  const adminAuth = await authorize_admin_join(adminConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      grade: "regular" as const,
    },
  });
  typia.assert(adminAuth);
  // 3. Create seller account for product and variant creation
  const sellerConnection: api.IConnection = { host: connection.host };
  const sellerAuth = await authorize_seller_join(sellerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  typia.assert(sellerAuth);
  // 4. Admin creates category
  const category = await generate_random_shopping_mall_admin_categories_create(
    adminConnection,
    {},
  );
  typia.assert(category);
  // 5. Seller creates product
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        shopping_mall_category_id: category.id,
      },
    },
  );
  typia.assert(product);
  // 6. Seller creates product variant
  const variant = await generate_random_shopping_mall_seller_variants_create(
    sellerConnection,
    {
      body: {
        shopping_mall_product_id: product.id,
      },
    },
  );
  typia.assert(variant);
  // 7. Customer adds variant to cart
  const cartItem = await generate_random_shopping_mall_member_cart_items_create(
    memberConnection,
    {
      body: {
        product_variant_id: variant.id,
      },
    },
  );
  typia.assert(cartItem);
  // 8. Customer creates shipping address
  const address = await generate_random_shopping_mall_member_addresses_create(
    memberConnection,
    {},
  );
  typia.assert(address);
  // 9. Customer places order
  const order = await generate_random_shopping_mall_member_orders_create(
    memberConnection,
    {
      body: {
        shopping_mall_customer_address_id: address.id,
      },
    },
  );
  typia.assert(order);
  // Extract order item for review
  const orderItem = order.orderItems[0];
  TestValidator.predicate("order has items", order.orderItems.length > 0);
  // 10. Customer creates review for delivered order item
  const review = await generate_random_shopping_mall_member_reviews_create(
    memberConnection,
    {
      body: {
        shopping_mall_product_id: product.id,
        shopping_mall_order_id: order.id,
        shopping_mall_order_item_id: orderItem.id,
      },
    },
  );
  typia.assert(review);
  // 11. Retrieve snapshot using review ID and snapshot ID
  // Snapshot retrieval endpoint validates ownership and snapshot existence
  // Access is restricted to review owner and administrators
  const snapshot =
    await api.functional.shoppingMall.member.reviews.snapshots.at(
      memberConnection,
      {
        reviewId: review.id,
        snapshotId: typia.random<string & tags.Format<"uuid">>(),
      },
    );
  typia.assert(snapshot);
  // 12. Validate snapshot data integrity
  TestValidator.equals(
    "snapshot review reference",
    snapshot.review.id,
    review.id,
  );
  TestValidator.predicate(
    "snapshot rating in valid range",
    snapshot.rating >= 1 && snapshot.rating <= 5,
  );
  TestValidator.predicate(
    "snapshot content matches type",
    typeof snapshot.content === "string" || snapshot.content === null,
  );
}

