   * @param connection
   * @param body Refresh token for obtaining new access token.
   * @x-autobe-authorization-type refresh
   * @x-autobe-authorization-actor seller
   * @x-autobe-specification Refresh JWT access token using valid refresh token. Validate refresh token against shopping_mall_seller_sessions. Check session is not expired (expired_at > now). Verify seller account is still active and approved. Generate new access token and optionally new refresh token. Update session expired_at if rotating refresh tokens.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("refresh")
  public async refresh(
    @TypedBody()
    body: IShoppingMallSeller.IRefresh,
  ): Promise<IShoppingMallSeller.IAuthorized> {
    try {
      return await postShoppingMallAuthSellerRefresh({
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
