import { IShoppingMallReview } from "../../../../api/structures/IShoppingMallReview";
import { patchShoppingMallProductsProductIdReviews } from "../../../../providers/patchShoppingMallProductsProductIdReviews";

@Controller("/shoppingMall/products/:productId/reviews")
export class ShoppingmallProductsReviewsController {
  /**
   * Retrieve paginated list of customer reviews for a specific product.
   *
   * This endpoint returns all non-deleted reviews for the specified product, sorted by newest first to show recent customer feedback prominently. The response includes review summaries with rating, optional content, customer information, and creation timestamp.
   *
   * Reviews are filtered to exclude soft-deleted entries, ensuring only active customer feedback is displayed. The average product rating is calculated from these non-deleted reviews and displayed separately on product pages.
   *
   * The endpoint supports pagination parameters for efficient browsing of large review collections. Additional filters may include rating range, date range, and content search criteria.
   *
   * @param connection
   * @param productId Product identifier (UUID format) to filter reviews.
   * @param body Search criteria including pagination parameters, rating filters, date range, and sorting options for product reviews.
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor null
   * @x-autobe-specification Query shopping_mall_reviews table filtered by shopping_mall_product_id. Exclude soft-deleted reviews (deleted_at IS NOT NULL). Sort by created_at DESC (newest first). Apply pagination using cursor-based or offset-based approach. Join with shopping_mall_members to include customer display name in response. Return IPageIShoppingMallReview.ISummary with pagination metadata. Validate productId exists in shopping_mall_products table before querying reviews.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Patch()
  public async index(
    @TypedParam("productId")
    productId: string & tags.Format<"uuid">,
    @TypedBody()
    body: IShoppingMallReview.IRequest,
  ): Promise<IPageIShoppingMallReview.ISummary> {
    try {
      return await patchShoppingMallProductsProductIdReviews({
        productId,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}
